    'my-work':['งานของฉัน','Personal work hub','จัดการงานสำคัญ งานประจำ และสิ่งที่ต้องส่งมอบในแต่ละวัน'],
    'team-board':['บอร์ดงานทีม','Team task board','ติดตามสถานะงานของทีม แก้ไขปัญหาคอขวด และจัดสมดุลภาระงาน'],
    projects:['โครงการทั้งหมด','Projects workspace','โครงการที่เชื่อมโยงงานประจำวันกับผลลัพธ์เชิงยุทธศาสตร์'],
    'project-detail':['รายละเอียดโครงการ','Project workspace','แผนงาน Milestone งานในโครงการ และหลักฐานส่งมอบ'],
    roadmap:['แผนพัฒนา IT','Strategic roadmap','มองภาพงานรายเดือนและความเชื่อมโยงระหว่างโครงการ'],
